import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.DPTp4bo7.js";const g=JSON.parse('{"title":"Tutorial: Floating Devices in Farming Areas","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/tutorial-floating-devices-in-farming-areas"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/tutorial-floating-devices-in-farming-areas"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/tutorial-floating-devices-in-farming-areas"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/tutorial-floating-devices-in-farming-areas"}]]},"headers":[],"relativePath":"tutorial-floating-devices-in-farming-areas.md","filePath":"logistics/src/page-Vr9I6TOU6zz1MfmH7lI3YN.md"}'),d={name:"tutorial-floating-devices-in-farming-areas.md"};function o(r,e,n,c,l,h){return a(),i("div",null,[...e[0]||(e[0]=[s('<div class="logistics-content"><span class="logistics-source-anchor" id="种植区浮空设备教程" aria-hidden="true"></span><h1 id="tutorial-floating-devices-in-farming-areas" tabindex="-1">Tutorial: Floating Devices in Farming Areas <a class="header-anchor" href="#tutorial-floating-devices-in-farming-areas" aria-label="Permalink to &quot;Tutorial: Floating Devices in Farming Areas&quot;">​</a></h1><blockquote><p>Source page ID: <code>Vr9I6TOU6zz1MfmH7lI3YN</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Vr9I6TOU6zz1MfmH7lI3YN" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Contributor: 卖兔子的小智乃</p><p>Last updated: 2026/10/20</p><p>Video: <a href="https://www.bilibili.com/video/BV1FkJB6oEuq/?share_source=copy_web&amp;vd_source=3f694229593884198d970b1b1211f6cd" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1FkJB6oEuq</a></p><p><span id="source-block-QNLhap628GkZ1M5rF6L4oJ"></span></p><span class="logistics-source-anchor" id="前言" aria-hidden="true"></span><h2 id="foreword" tabindex="-1">Foreword <a class="header-anchor" href="#foreword" aria-label="Permalink to &quot;Foreword&quot;">​</a></h2><p>At present, this tutorial&#39;s device-floating technique works only in the farming areas in Wuling City and Si&#39;s Painting. Because of the height limit for floating devices, it can be used only to overlap fields and devices; it cannot overlap one device with another.</p><p><strong>Because of the height-detection issue, a floating sprinkler cannot detect fields, so sprinklers cannot be floated.</strong></p><p><span id="source-block-PVoqXuxCYX2DQnYmoq0LR7"></span></p><span class="logistics-source-anchor" id="作用" aria-hidden="true"></span><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Floating devices allows upgraded fields to receive a higher adjacent-crop bonus. The best field layout is given in <a href="/endfield-skydoc/planting-and-automatic-harvester-mechanics-research-and-applications">Research and Application of Farming and Automatic Harvester Mechanics</a>.</p><p><span id="source-block-dfTMIfq1lb9l2cOd38SyHr"></span></p><span class="logistics-source-anchor" id="实现方法" aria-hidden="true"></span><h2 id="method" tabindex="-1">Method <a class="header-anchor" href="#method" aria-label="Permalink to &quot;Method&quot;">​</a></h2><p>Devices and pipe parts <strong>with pipe entrances or exits</strong> (pipe splitters, pipe mergers, and pipe bridges) can be floated. There are two methods. <strong>Fields can be placed before floating a device; this does not affect the process and makes it easier to see whether the device has floated successfully.</strong></p><p><span id="source-block-QR1sFqVLeEWRkpvF8lDUAB"></span></p><span class="logistics-source-anchor" id="方法一-视频中的方法" aria-hidden="true"></span><h3 id="method-1-the-method-used-in-the-video" tabindex="-1">Method 1 (the method used in the video) <a class="header-anchor" href="#method-1-the-method-used-in-the-video" aria-label="Permalink to &quot;Method 1 (the method used in the video)&quot;">​</a></h3><p>Step 1: Choose the intended device position. Place a pipe part at a nearby higher position and draw a pipe starting from it.</p><p>Step 2: Extend the pipe to a point three grid spaces beyond the intended device port, then place the pipe. (On PC, press R to change the pipe&#39;s priority direction.)</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-dbcf2d17c6225813.q90-d16d4e8c7e0bbef5.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-f75c5029c5d2f504.q90-0626a48d36e941cc.webp" alt="Image"></td></tr></tbody></table><p>Step 3: Delete the three pipe segments at the end.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-d5547f1723d6be2c.q90-a53e13326ddd8c6f.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-120ae78e8f1409f2.q90-6a3cb41558e961c1.webp" alt="Image"></td></tr></tbody></table><p>Step 4: Align the device&#39;s pipe port with the pipe and place the device. (If the device has only a pipe exit, reverse the pipe flow direction first.)</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-d4774003c23f05f2.q90-89eb710db9befdc3.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-e058f4e580b5c509.q90-b892675fc535f100.webp" alt="Image"></td></tr></tbody></table><p><span id="source-block-KcO4BV4zbF18YByBzjF9zW"></span></p><span class="logistics-source-anchor" id="方法二-最稳-需要先用一次方法一" aria-hidden="true"></span><h3 id="method-2-most-stable-method-1-must-be-used-once-first" tabindex="-1">Method 2 (most stable; Method 1 must be used once first) <a class="header-anchor" href="#method-2-most-stable-method-1-must-be-used-once-first" aria-label="Permalink to &quot;Method 2 (most stable; Method 1 must be used once first)&quot;">​</a></h3><p>Tests show that a device can be floated by connecting it to a device or pipe part that is already floating, which gives us the second method. This method is the most stable and can reliably float devices in places where Method 1 is less reliable, but it requires a floating device or pipe part produced by Method 1. <strong>Before using Method 2, it is best to place the fields first so that the pipe parts are not placed directly on the ground.</strong></p><p>Step 1: Choose the intended device position. Draw a pipe from the pipe exit of an already-floating device or pipe part to the intended position. (If there is only a pipe entrance, first place a pipe splitter against the entrance, then draw the pipe from the splitter&#39;s exit.)</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-1e19d67b251595cd.q90-f236dc91c4c4778d.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-66fc887e8e7c1026.q90-db760729c847bfcb.webp" alt="Image"></td></tr></tbody></table><p>Step 2: Place pipe parts along the pipe.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-4e31536ef53132ae.q90-dfc3549b6b5118a7.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-f80a139ab4a09486.q90-5a888dd63fd75ae0.webp" alt="Image"></td></tr></tbody></table><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-acf36ff3e6860cb7.q90-c445e96d58dbe776.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-73d8a9df1d294e88.q90-11393641e1d5b1d9.webp" alt="Image"></td></tr></tbody></table><p>Step 3: Align the device&#39;s pipe port with the pipe part and place the device.</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-f4df7cd3fd4e3beb.q90-27f37adbe2097f2f.webp" alt="Image"></td><td><img src="/endfield-skydoc/logistics/src/assets/images/img-9a679f3060b7cb2b.q90-78f0e5e0099c2636.webp" alt="Image"></td></tr></tbody></table></div>',1)])])}const f=t(d,[["render",o]]);export{g as __pageData,f as default};
